import type { Metadata } from "next";
import { db } from "@/lib/db";
import { ToolShell, FaqJsonLd, type ToolFaq } from "@/components/marketing/ToolShell";
import { ServerSizeCalculatorTool } from "@/components/marketing/tools/ServerSizeCalculatorTool";
import { relatedTools } from "@/lib/tools/catalog";
import type { PlanSpec } from "@/lib/tools/server-sizing";

export const dynamic = "force-dynamic";

export const metadata: Metadata = {
  title: "Server Size Calculator — How Much RAM & CPU Do I Need?",
  description:
    "Free VPS & game server size calculator. Pick your use case (Minecraft, Rust, Palworld, Valheim, ARK, WordPress, Node.js, Discord bot and more) and your scale to get a RAM, CPU and storage recommendation mapped to a real Nxeon plan.",
  alternates: { canonical: "/tools/server-size-calculator" },
};

const faq: ToolFaq[] = [
  {
    q: "How much RAM do I need for a game server?",
    a: "It depends on the game and player count. Minecraft is roughly 1 GB per 5 players; Valheim wants 4-8 GB; Rust 8-16 GB; Palworld and ARK: Survival Ascended start at 16 GB. Pick your game and slide the player count and the calculator gives a concrete figure and matching plan.",
  },
  {
    q: "How is the recommendation calculated?",
    a: "Each workload has a researched RAM/CPU/storage baseline that scales with players or traffic. We then map the requirement onto the smallest live Nxeon plan that satisfies it — the plans and prices shown come straight from our catalogue, not made-up numbers.",
  },
  {
    q: "Does CPU or RAM matter more?",
    a: "For many game servers (Minecraft, FiveM, Rust) single-thread CPU clock speed matters as much as RAM — adding memory won't fix tick lag caused by a slow core. Our plans pair fast cores with generous RAM for exactly this reason.",
  },
  {
    q: "What if my workload is bigger than any plan?",
    a: "The calculator says so honestly and points you at our largest plan, plus block storage for capacity or a custom/dedicated box for very large servers. With full root access you can also resize a running VPS as you grow.",
  },
];

export default async function Page() {
  const rows = await db.plan
    .findMany({
      where: { active: true },
      orderBy: { sortOrder: "asc" },
      select: { slug: true, name: true, cpuCores: true, ramMB: true, diskGB: true, priceCents: true },
    })
    .catch(() => [] as PlanSpec[]);

  return (
    <>
      <FaqJsonLd faq={faq} />
      <ToolShell
        category="Server tool"
        title="Server Size Calculator"
        description="Tell us what you're hosting and at what scale — get a RAM, CPU and storage recommendation mapped to a real Nxeon plan, with the price."
        about={[
          {
            heading: "What VPS or game server do you actually need?",
            body: (
              <p>
                Over-provisioning wastes money; under-provisioning means lag and crashes. This
                calculator turns a use case and a scale — players for a game server, traffic for a
                website — into a concrete <b>RAM, CPU and storage</b> recommendation, then maps it to
                the smallest Nxeon plan that comfortably fits, with the real monthly price.
              </p>
            ),
          },
          {
