import Link from "next/link";
import { PageHeader } from "@/components/ui/primitives";

/**
 * Shared chrome for an in-portal free-tool page: a small "back to all tools"
 * link, the standard portal PageHeader, and a `.card` wrapper around the reused
 * marketing tool component so it sits inside the dashboard Shell consistently
 * with the rest of the portal. Lives under app/dashboard/tools/ as a private
 * (underscore-prefixed) module so Next never treats it as a route.
 */
export function ToolPage({
  title,
  sub,
  children,
}: {
  title: string;
  sub: string;
  children: React.ReactNode;
}) {
  return (
    <div>
      <Link
