}

import Link from "next/link";
import { PageHeader } from "@/components/ui/primitives";
import { toolsByCategory, TOOLS, type Tool, type ToolCategory } from "@/lib/tools/catalog";
import {
  IconGlobe,
  IconNetwork,
  IconServer,
  IconLock,
  IconCode,
  IconGauge,
  IconShield,
  IconTerminal,
  IconSpark,
  IconGame,
} from "@/components/marketing/icons";

const ICONS: Record<string, (p: { size?: number }) => React.ReactNode> = {
  globe: IconGlobe,
  network: IconNetwork,
  server: IconServer,
  lock: IconLock,
  code: IconCode,
  gauge: IconGauge,
  shield: IconShield,
  terminal: IconTerminal,
  spark: IconSpark,
  game: IconGame,
};

// Same grouping copy as the public /tools hub, so the in-portal directory reads
// identically to the marketing suite it mirrors.
const CATEGORY_BLURB: Record<ToolCategory, string> = {
  Network: "Diagnose domains, DNS, ports and certificates — the checks you run before and after every deploy.",
  Developer: "Everyday encode/format/generate utilities that run entirely in your browser.",
  Security: "Generate strong secrets and hashes locally — nothing is ever sent to a server.",
  Servers: "Check a game server, size your next box, and measure real latency to Nxeon.",
};

function ToolCard({ tool }: { tool: Tool }) {
  const Icon = ICONS[tool.icon] ?? IconServer;
  return (
    <Link href={`/dashboard/tools/${tool.slug}`} className="card card-hover group flex h-full flex-col">
      <div className="mb-4 inline-flex w-fit rounded-xl border border-white/[0.08] bg-gradient-to-br from-accent-blue/20 to-brand-500/20 p-3 text-brand-300 transition-transform duration-200 group-hover:scale-105">
        {Icon({ size: 22 })}
      </div>
      <h3 className="flex items-center gap-1.5 text-base font-semibold text-white">
        {tool.name}
        {!tool.serverSide && (
          <span className="rounded-full border border-emerald-500/25 bg-emerald-500/10 px-1.5 py-0.5 text-[10px] font-semibold text-emerald-300">
            In-browser
          </span>
        )}
      </h3>
      <p className="mt-2 flex-1 text-sm leading-relaxed text-slate-400">{tool.tagline}</p>
    </Link>
  );
}

export default function DashboardToolsPage() {
  const grouped = toolsByCategory();
  const order: ToolCategory[] = ["Servers", "Network", "Developer", "Security"];

  return (
    <div>
      <PageHeader
        title="Free tools"
        sub={`${TOOLS.length} networking, server and developer utilities — right inside your dashboard. No signup, no limits.`}
      />

      <div className="space-y-10">
        {order.map((cat) => (
          <section key={cat}>
            <p className="section-label">{cat} tools</p>
            <p className="mt-1 max-w-2xl text-sm text-slate-400">{CATEGORY_BLURB[cat]}</p>
            <div className="mt-5 grid gap-5 sm:grid-cols-2 lg:grid-cols-3">
              {grouped[cat].map((t) => (
                <ToolCard key={t.slug} tool={t} />
              ))}
            </div>
          </section>
        ))}
      </div>
    </div>
  );
}

