// force-dynamic mirrors the marketing route: the recommendation maps onto the
// live plan catalogue, which is read fresh from the DB per request.
export const dynamic = "force-dynamic";

export default async function Page() {
  const rows = await db.plan
    .findMany({
      where: { active: true },
      orderBy: { sortOrder: "asc" },
      select: { slug: true, name: true, cpuCores: true, ramMB: true, diskGB: true, priceCents: true },
    })
    .catch(() => [] as PlanSpec[]);

  return (
    <ToolPage
      title="Server Size Calculator"
      sub="How much RAM, CPU & storage do you need? Get a plan recommendation."
    >
      <ServerSizeCalculatorTool plans={rows} />
    </ToolPage>
  );
}
